    descriptionAdvanced: {
      de: "Namyangju ist eine bedeutende Stadt in der Provinz Gyeonggi, nordöstlich von Seoul gelegen, die für ihre harmonische Verbindung von Natur und Kultur bekannt ist. Die Stadt dient aufgrund ihrer Nähe zur Hauptstadt als wichtiger Wohnstandort, hat aber gleichzeitig weite Grünflächen und Berge bewahrt. Ein historisches Highlight ist das Grab von Dasan Jeong Yak-yong, einem der bedeutendsten Gelehrten der späten Joseon-Dynastie, dessen Philosophie des Silhak hier tief verwurzelt ist. Geografisch wird Namyangju vom Bukhangang (Nord-Han-Fluss) geprägt, der eine malerische Kulisse bietet und zur Trinkwasserversorgung der Region beiträgt. Die Stadt beherbergt zudem das Kofic Namyangju Studio, eines der größten Filmstudios Asiens, in dem zahlreiche bekannte koreanische Filme und Serien gedreht wurden. In kultureller Hinsicht sind die königlichen Gräber der Joseon-Dynastie, wie Hongneung und Yureung, die ebenfalls zum UNESCO-Weltkulturerbe gehören, von herausragender Bedeutung. Namyangju fördert aktiv den ökologischen Landbau und ist ein Zentrum für die Slow-Food-Bewegung in Korea.",
      hu: "Namyangju egy jelentős város Gyeonggi tartományban, Szöultól északkeletre, amely a természet és a kultúra harmonikus kapcsolatáról ismert. A város a főváros közelsége miatt fontos lakóövezetként szolgál, de ugyanakkor tágas zöldfelületeket és hegyeket is megőrzött. Történelmi kiemelkedő pontja Dasan Jeong Yak-yong sírja, aki a késői Csoszon-dinasztia egyik legjelentősebb tudósa volt, és akinek a Silhak (gyakorlati tanulás) filozófiája mélyen gyökerezik itt. Földrajzilag Namyangju a Bukhangang (Északi-Han-folyó) mentén terül el, amely festői hátteret biztosít és hozzájárul a régió ivóvízellátásához. A város ad otthont a Kofic Namyangju Studiónak is, amely Ázsia egyik legnagyobb filmstúdiója, és ahol számos ismert koreai filmet és sorozatot forgattak. Kulturális szempontból kiemelkedő jelentőségűek a Csoszon-dinasztia királyi sírjai, mint például Hongneung és Yureung, amelyek szintén az UNESCO Világörökség részét képezik. Namyangju aktívan támogatja az ökológiai mezőgazdaságot.",
      ro: "Namyangju este un oraș important din provincia Gyeonggi, situat la nord-est de Seul, cunoscut pentru legătura sa armonioasă între natură și cultură. Datorită proximității sale față de capitală, orașul servește drept o zonă rezidențială majoră, păstrând în același timp spații verzi vaste și munți. Un punct istoric de referință este mormântul lui Dasan Jeong Yak-yong, unul dintre cei mai eminenți savanți din perioada târzie a dinastiei Joseon, a cărui filozofie Silhak (învățarea practică) este profund înrădăcinată aici. Din punct de vedere geografic, Namyangju este marcat de râul Bukhangang (râul Han de Nord), care oferă un cadru pitoresc și contribuie la alimentarea cu apă a regiunii. Orașul găzduiește, de asemenea, studioul Kofic Namyangju, unul dintre cele mai mari studiouri cinematografice din Asia, unde au fost filmate numeroase producții coreene. Mormintele regale ale dinastiei Joseon, precum Hongneung și Yureung, fac parte din patrimoniul mondial UNESCO.",
      en: "Namyangju is a prominent city in Gyeonggi Province, situated northeast of Seoul, known for its harmonious blend of nature and culture. Due to its proximity to the capital, the city serves as a vital residential area while simultaneously preserving extensive green spaces and mountains. A historical highlight is the tomb of Dasan Jeong Yak-yong, one of the most eminent scholars of the late Joseon Dynasty, whose Silhak (practical learning) philosophy is deeply rooted here. Geographically, Namyangju is defined by the Bukhangang (North Han River), which provides a picturesque backdrop and contributes to the region's water supply. The city is also home to the Kofic Namyangju Studio, one of Asia's largest film production facilities, where many famous Korean movies and dramas have been filmed. Culturally, the Royal Tombs of the Joseon Dynasty, such as Hongneung and Yureung, which are UNESCO World Heritage sites, hold significant importance. Namyangju actively promotes organic farming and serves as a major hub for the Slow Food movement in South Korea.",
      es: "Namyangju es una ciudad en la provincia coreana de Gyeonggi, situada al noreste de Seúl. La ciudad se extiende sobre 458 km² y tiene una población de unos 700.000 habitantes (2023). Es conocida por sus numerosos espacios verdes y sitios históricos, incluido el cementerio real de la dinastía Joseon (UNESCO). Namyangju es una importante zona residencial para los viajeros a Seúl. La economía incluye la agricultura (arroz, verduras) y los servicios. El río Bukhan atraviesa la ciudad.",
      pt: "Namyangju é uma cidade na província coreana de Gyeonggi, situada a nordeste de Seul. A cidade estende-se por 458 km² e tem uma população de cerca de 700.000 habitantes (2023). É conhecida pelos seus numerosos espaços verdes e locais históricos, incluindo o cemitério real da dinastia Joseon (UNESCO). Namyangju é uma importante zona residencial para quem viaja para Seul. A economia inclui a agricultura (arroz, legumes) e os serviços. O rio Bukhan atravessa a cidade.",
      fr: "Namyangju est une ville de la province coréenne du Gyeonggi, située au nord-est de Séoul. La ville s'étend sur 458 km² et compte environ 700 000 habitants (2023). Elle est connue pour ses nombreux espaces verts et sites historiques, dont le cimetière royal de la dynastie Joseon (UNESCO). Namyangju est une zone résidentielle importante pour les navetteurs travaillant à Séoul. L'économie comprend l'agriculture (riz, légumes) et les services. La rivière Bukhan traverse la ville.",
    },
