      hu: ["Namyangju a híres tudós, Jeong Yak-yong szülőhelye.", "A városban található a Kofic Stúdió, a filmipar egyik nagy központja.", "Namyangju területén több UNESCO-védettségű királyi sírhely van.", "A Bukhangang-folyó keresztülfolyik a város területén.", "Namyangju a nemzetközi Slow Food mozgalom egyik hivatalos központja.", "A város lakossága meghaladja a 700 000 főt."],
      ro: ["Namyangju este locul de naștere al celebrului savant Jeong Yak-yong.", "Orașul găzduiește Studioul Kofic, un centru major al industriei de film.", "În Namyangju se află mai multe morminte regale Joseon din patrimoniul UNESCO.", "Râul Bukhangang traversează teritoriul orașului.", "Namyangju este un centru oficial al mișcării internaționale Slow Food.", "Orașul are o populație de peste 700.000 de locuitori."],
      en: ["Namyangju is the birthplace of the famous scholar Jeong Yak-yong.", "The city hosts the Kofic Studio, a major hub for the film industry.", "Several UNESCO-listed Joseon Royal Tombs are located in Namyangju.", "The Bukhangang River flows through the city's territory.", "Namyangju is an official center for the international Slow Food movement.", "The city has a population of over 700,000 residents."],
      es: ["Superficie: 458 km²", "Población: 700.000 (2023)", "Patrimonio Mundial de la UNESCO: Tumbas reales de Joseon (desde 2009)", "Río: Bukhan, longitud 43 km en la ciudad", "Proporción de viajeros: 60% hacia Seúl", "Superficie agrícola: 150 km²"],
