      ro: ["Cascada Jeongbang are o înălțime de 23 de metri.", "Stâncile Jusangjeolli s-au format acum aproximativ 250.000 de ani.", "Seogwipo a fost unul dintre orașele gazdă ale CM de Fotbal din 2002.", "Mandarinele Hallabong sunt numite după muntele Hallasan.", "Orașul are o populație de aproximativ 180.000 de locuitori.", "Muzeul Teddy Bear din Seogwipo este unul dintre cele mai mari din lume."],
