      en: ["The POSCO Gwangyang Steelworks is the largest integrated steel mill in the world by area.", "Gwangyang Port is one of the most significant container hubs in Northeast Asia.", "The Gwangyang Maehwa Festival is a premier spring flower festival in Korea.", "Baegunsan Mountain reaches a peak elevation of 1,222 meters.", "The city is famous for its local culinary specialty, Gwangyang-style bulgogi.", "Gwangyang was officially incorporated as a city in 1989."],
      es: ["Población: aprox. 140.000 (2020)", "Superficie: 448 km²", "Acería: Gwangyang Works, inaugurada en 1985, capacidad anual 20 millones de toneladas", "Puerto: Puerto de Gwangyang, manipulación de contenedores 2,5 millones de TEU (2020)", "Humedal: Ulsu-got, área Ramsar desde 2010", "Complejo industrial: Complejo Industrial Nacional de Gwangyang, 33 km²"],
      pt: ["População: aprox. 140.000 (2020)", "Área: 448 km²", "Siderúrgica: Gwangyang Works, inaugurada em 1985, capacidade anual 20 milhões de toneladas", "Porto: Porto de Gwangyang, movimentação de contentores 2,5 milhões de TEU (2020)", "Área úmida: Ulsu-got, área Ramsar desde 2010", "Complexo industrial: Complexo Industrial Nacional de Gwangyang, 33 km²"],
